import { Order } from './types';

export interface Cursor { createdAt: string; id: string }

function compare(a: Order, b: Order): number {
  if (a.createdAt < b.createdAt) return -1;
  if (a.createdAt > b.createdAt) return 1;
  if (a.id < b.id) return -1;
  if (a.id > b.id) return 1;
  return 0;
}

function isAfter(row: Order, after?: Cursor): boolean {
  if (!after) return true;
  if (row.createdAt > after.createdAt) return true;
  if (row.createdAt < after.createdAt) return false;
  return row.id > after.id;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  list(tenant: string, after?: Cursor): Order[] {
    return this.rows
      .filter(row => row.tenant === tenant && isAfter(row, after))
      .sort(compare);
  }
}
```

