```ts
import { Order } from './types';

/** Position key used for cursor pagination: (createdAt, id) in ascending lexicographic order. */
export interface OrderKey {
  createdAt: string;
  id: string;
}

function compareOrders(a: Order, b: Order): number {
  if (a.createdAt < b.createdAt) return -1;
  if (a.createdAt > b.createdAt) return 1;
  if (a.id < b.id) return -1;
  if (a.id > b.id) return 1;
  return 0;
}

function isAfterKey(row: Order, after?: OrderKey): boolean {
  if (after === undefined) return true;
  if (row.createdAt !== after.createdAt) return row.createdAt > after.createdAt;
  return row.id > after.id;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  /**
   * Rows for `tenant`, ascending by (createdAt, id), strictly after `after` when given.
   * Does not mutate the backing rows.
   */
  list(tenant: string, after?: OrderKey): Order[] {
    return this.rows
      .filter(row => row.tenant === tenant && isAfterKey(row, after))
      .sort(compareOrders);
  }
}
```

