import { OrderRepository, OrderKey } from './repository';
import { ListRequest, Page } from './types';

function parseCursor(cursor: string): OrderKey {
  if (typeof cursor !== 'string') throw new Error('invalid request');
  const parts = cursor.split('|');
  if (parts.length !== 2 || parts[0] === '' || parts[1] === '') throw new Error('invalid request');
  return { createdAt: parts[0], id: parts[1] };
}

export class OrderHandler {
  constructor(private readonly repository: OrderRepository) {}

  list(request: ListRequest): Page {
    if (!request || typeof request !== 'object') throw new Error('invalid request');
    if (!request.tenant || !Number.isInteger(request.limit) || request.limit < 1 || request.limit > 100) {
      throw new Error('invalid request');
    }
    const after = request.cursor === undefined ? undefined : parseCursor(request.cursor);
    // Filtering (tenant) happens in the repository; pagination applies to filtered rows only.
    const matches = this.repository.list(request.tenant, after);
    const window = matches.slice(0, request.limit + 1);
    const items = window.slice(0, request.limit);
    const last = items.length > 0 ? items[items.length - 1] : undefined;
    return {
      items,
      nextCursor: window.length > request.limit && last ? `${last.createdAt}|${last.id}` : null,
    };
  }
}
